create or replace function public.quest_creator_authorized(p_owner_type text,p_owner_id uuid) returns boolean language plpgsql security definer set search_path=public as $$ declare a jsonb; b record; begin if auth.uid() is null then return false; end if; if p_owner_type='admin' then a:=public.admin_authorization_v1(); return coalesce((a->>'authorized')::boolean,false) or coalesce((a->>'is_admin')::boolean,false) or coalesce((a->>'is_owner')::boolean,false); end if; select * into b from public.get_business_product_access(p_owner_id) limit 1; if not found then return false; end if; if p_owner_type='business' then return b.is_admin or b.business_id=p_owner_id; end if; if p_owner_type='fleet' then return b.is_admin or b.fleet_enabled; end if; if p_owner_type='enterprise' then return b.is_admin or b.enterprise_enabled; end if; return false; end $$;
create or replace function public.quest_create(p_owner_type text,p_owner_id uuid,p_name text,p_description text default null,p_reward_config jsonb default '{}'::jsonb,p_targeting_config jsonb default '{}'::jsonb,p_route_config jsonb default '{}'::jsonb,p_start_at timestamptz default null,p_end_at timestamptz default null) returns public.quests language plpgsql security definer set search_path=public as $$ declare q public.quests; begin if not public.quest_creator_authorized(p_owner_type,p_owner_id) then raise exception 'Not authorized to create quest'; end if; insert into public.quests(owner_type,owner_id,name,description,reward_config,targeting_config,route_config,start_at,end_at) values(p_owner_type,p_owner_id,p_name,p_description,coalesce(p_reward_config,'{}'::jsonb),coalesce(p_targeting_config,'{}'::jsonb),coalesce(p_route_config,'{}'::jsonb),p_start_at,p_end_at) returning * into q; return q; end $$;
create or replace function public.quest_add_step(p_quest_id uuid,p_step_order integer,p_step_type text,p_title text,p_description text default null,p_location_id uuid default null,p_geofence_id uuid default null,p_qr_code_id uuid default null,p_required boolean default true,p_xp_reward integer default 0,p_reward_config jsonb default '{}'::jsonb,p_validation_config jsonb default '{}'::jsonb) returns public.quest_steps language plpgsql security definer set search_path=public as $$ declare q public.quests; s public.quest_steps; begin select * into q from public.quests where id=p_quest_id; if not found or not public.quest_creator_authorized(q.owner_type,q.owner_id) then raise exception 'Not authorized to edit quest'; end if; insert into public.quest_steps(quest_id,step_order,step_type,title,description,location_id,geofence_id,qr_code_id,required,xp_reward,reward_config,validation_config) values(p_quest_id,p_step_order,p_step_type,p_title,p_description,p_location_id,p_geofence_id,p_qr_code_id,coalesce(p_required,true),greatest(0,coalesce(p_xp_reward,0)),coalesce(p_reward_config,'{}'::jsonb),coalesce(p_validation_config,'{}'::jsonb)) returning * into s; return s; end $$;
create or replace function public.quest_set_status(p_quest_id uuid,p_status text) returns public.quests language plpgsql security definer set search_path=public as $$ declare q public.quests; begin select * into q from public.quests where id=p_quest_id; if not found or not public.quest_creator_authorized(q.owner_type,q.owner_id) then raise exception 'Not authorized to edit quest'; end if; update public.quests set status=p_status,updated_at=now() where id=p_quest_id returning * into q; return q; end $$;
create or replace function public.quest_list_creator(p_owner_type text,p_owner_id uuid) returns setof public.quests language plpgsql security definer set search_path=public as $$ begin if not public.quest_creator_authorized(p_owner_type,p_owner_id) then raise exception 'Not authorized to list quests'; end if; return query select * from public.quests where owner_type=p_owner_type and owner_id=p_owner_id order by updated_at desc; end $$;
